tool_calls:
ls -la /data /release 2>/dev/null || true
cat /data/commits.log
which awk sed grep
mkdir -p /release
cat << 'EOF' > /tmp/parse.awk
BEGIN {
    feat_cnt = 0
    fix_cnt = 0
    other_cnt = 0
}
{
    line = $0
    # format: 'type(scope): message'
    if (match(line, /^([a-zA-Z0-9_-]+)\(([^)]+)\):[[:space:]]*(.*)$/, arr)) {
        type = arr[1]
        scope = arr[2]
        msg = arr[3]

        item = "- " scope ": " msg

        if (type == "feat") {
            feats[feat_cnt++] = item
        } else if (type == "fix") {
            fixes[fix_cnt++] = item
        } else {
            others[other_cnt++] = item
        }
    }
}
END {
    print "## Features"
    for (i = 0; i < feat_cnt; i++) {
        print feats[i]
    }
    print ""
    print "## Bug Fixes"
    for (i = 0; i < fix_cnt; i++) {
        print fixes[i]
    }
    print ""
    print "## Other"
    for (i = 0; i < other_cnt; i++) {
        print others[i]
    }
}
EOF
awk -f /tmp/parse.awk /data/commits.log
awk -f /tmp/parse.awk /data/commits.log > /release/CHANGELOG.md
cat /release/CHANGELOG.md
ls -l /release/CHANGELOG.md

